{
  "claims": [
    {
      "claim": "Direct PET/radiotracer data explicitly covering [11C]tariquidar, the compound matching the query scaffold, report very low brain distribution in humans and rodents and attribute it to ABCB1/ABCG2/P-gp efflux.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 3"
      ],
      "record_ids": [
        "Record 3-1",
        "Record 3-9",
        "Record 3-10"
      ]
    },
    {
      "claim": "The closest tested fluorinated analogue [18F]4 is a dual P-gp/Bcrp substrate: brain AUC was 8-9-fold higher in P-gp/Bcrp knockout mice and ~7-fold higher after P-gp/Bcrp inhibition, directly showing efflux-limited brain exposure in this exact chemotype.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 16"
      ],
      "record_ids": [
        "Record 16-2",
        "Record 16-4",
        "Record 16-5",
        "Record 16-6"
      ]
    },
    {
      "claim": "The near-isosteric elacridar scaffold has very low direct brain uptake across species (human brain SUV ~0.1, rat peak ~0.5 SUV, human K1 0.003-0.007 min^-1) and is an ABCB1/ABCG2 substrate, consistent with poor CNS access for this inhibitor chemotype.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 3",
        "Molecule 11"
      ],
      "record_ids": [
        "Record 3-2",
        "Record 3-4",
        "Record 3-7",
        "Record 3-8",
        "Record 11-1",
        "Record 11-3"
      ]
    },
    {
      "claim": "An [18F]fluoroelacridar analogue had low baseline brain activity that increased several-fold only after dual P-gp/BCRP inhibition, confirming that efflux restricts brain entry in closely related compounds.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 1"
      ],
      "record_ids": [
        "Record 1-1"
      ]
    },
    {
      "claim": "Additional compounds with poor CNS exposure, including the THIQ-containing cilobradine and the P-gp/BCRP substrate imatinib, reinforce that neither the THIQ motif nor target potency guarantees meaningful BBB penetration, although their structural transferability is lower.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 8",
        "Molecule 6",
        "Molecule 10"
      ],
      "record_ids": [
        "Record 8-1",
        "Record 6-1",
        "Record 6-4",
        "Record 10-1"
      ]
    },
    {
      "claim": "One structurally related anthranilamide-quinoline analogue showed high wild-type brain uptake by PET despite being an efflux substrate; this is the strongest evidence for possible CNS access, but it is an analogue rather than direct [11C]tariquidar data and is outweighed by the consistent low-uptake/efflux-limited records.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2"
      ]
    },
    {
      "claim": "High brain uptake in less similar THIQ-containing radiotracers and PAMPA predictions on a remote diaryl amide support that simple THIQ ethers can enter brain, but they lack the large bis-amide/quinoline P-gp pharmacophore of the query, so their transferability is limited.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 2",
        "Molecule 4",
        "Molecule 5",
        "Molecule 7",
        "Molecule 9",
        "Molecule 15"
      ],
      "record_ids": [
        "Record 2-1",
        "Record 4-1",
        "Record 5-1",
        "Record 7-1",
        "Record 9-1",
        "Record 15-1"
      ]
    },
    {
      "claim": "A single mouse PET record reports high [11C]elacridar uptake, but it is an isolated, context-poor outlier against numerous species-consistent low-uptake and efflux records for the same compound, so it is given little weight.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 3"
      ],
      "record_ids": [
        "Record 3-6"
      ]
    }
  ],
  "final_prediction": "fail"
}

